import numpy as np
from collections import deque

grid = np.array([list(map(int, line.split())) for line in """9 6 1 8 7 9 0 2 7 7 3 9 7 7 5
2 5 7 7 3 7 7 7 8 7 9 5 2 7 3
7 3 5 0 7 2 7 7 6 7 2 2 1 9 7
3 7 9 5 6 7 7 7 2 0 8 1 7 7 7
6 7 7 7 7 1 7 7 0 0 9 7 1 7 3
7 7 3 0 7 7 7 7 2 7 7 7 7 8 5""".strip().split('\n')])

def closest_non7(grid):
    result = grid.copy()
    h, w = grid.shape
    for r in range(h):
        for c in range(w):
            if grid[r, c] == 7:
                best_dist = float('inf')
                best_val = 0

                # Same row
                for i in range(w):
                    if i != c and grid[r, i] != 7:
                        dist = abs(i - c)
                        if dist < best_dist:
                            best_dist = dist
                            best_val = grid[r, i]

                # Same column
                for i in range(h):
                    if i != r and grid[i, c] != 7:
                        dist = abs(i - r)
                        if dist < best_dist:
                            best_dist = dist
                            best_val = grid[i, c]

                # Diagonals
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] != 7:
                            dist = abs(nr - r) + abs(nc - c)
                            if dist < best_dist:
                                best_dist = dist
                                best_val = grid[nr, nc]

                result[r, c] = best_val
    return result

out_closest = closest_non7(grid)
print(out_closest)

