def replace_with_col_min(grid):
    result = grid.copy()
    for c in range(grid.shape[1]):
        col = grid[:, c]
        non7 = col[col != 7]
        if len(non7) > 0:
            result[grid[:, c] == 7, c] = np.min(non7)
    return result

print("=== Column min replacement ===")
